"""Deterministic Markdown reference derived from the live CLI schema."""

from __future__ import annotations

import json

from pynakes.capabilities import _command_schema, command_schemas


def _cell(value: object) -> str:
    return str(value).replace("|", "&#124;").replace("\n", " ")


def render_command_reference() -> str:
    """Render all leaf commands, including every option spelling and choice."""
    lines = [
        "# Command reference",
        "",
        "<!-- Generated by docs/hooks.py from the live CLI. Do not edit by hand. -->",
        "",
        "Every command below is **stable** under the CLI compatibility policy from",
        "0.7.0. Stable describes the contract, not a claim that 0.7.0 is released.",
        "The Python API remains experimental until 1.0. See",
        "[Public API and compatibility](public-api.md) and [Usage](usage.md).",
        "",
        "Library commands accept `--file` / `-f` as an alternative to the first",
        "positional library path. When one `.bib` exists in the working directory,",
        "commands that read a library can detect it. Optional operands are shown",
        "in brackets, and repeatable arguments end in `...`.",
        "",
    ]
    import typer.main

    from pynakes.cli import app

    schemas = {"": _command_schema(typer.main.get_command(app)), **command_schemas()}
    for name, schema in schemas.items():
        operands = []
        for arg in schema["arguments"]:
            operand = arg["name"].upper() + ("..." if arg.get("variadic") else "")
            operands.append(operand if arg["required"] else f"[{operand}]")
        synopsis = " ".join(part for part in ["pynakes", name, *operands, "[OPTIONS]"] if part)
        lines.extend(
            [
                f"## {name or 'Global options'}",
                "",
                f"**Stability: {schema['stability']}**",
                "",
                schema["help"],
                "",
                f"`{synopsis}`",
                "",
                "| Parameter | Type | Required | Default | Choices | Description |",
                "| --- | --- | --- | --- | --- | --- |",
            ]
        )
        for param in [*schema["arguments"], *schema["options"]]:
            spelling = ", ".join(param.get("flags", [param["name"].upper()]))
            default = (
                json.dumps(param["default"], ensure_ascii=False) if "default" in param else "—"
            )
            values = [
                f"`{spelling}`",
                param["type"],
                "yes" if param["required"] else "no",
                default,
                ", ".join(param.get("choices", [])) or "—",
                param.get("help", ""),
            ]
            lines.append("| " + " | ".join(_cell(value) for value in values) + " |")
        lines.append("")
    return "\n".join(lines)
